// MySpace\MyS_Front\src\paginas\perfil\EditarPerfil.jsx

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import MainLayout from '../../components/Layout';
import './EditarPerfil.css';
import { getPublicacionesPorPerfil, actualizarPerfil } from '../../Api';

// Helper para obtener usuario de forma segura
const getUsuarioLogeado = () => {
    try {
        const data = localStorage.getItem("usuarioLogeado");
        return data ? JSON.parse(data) : null;
    } catch (error) {
        console.error("Error al leer usuario:", error);
        return null;
    }
};

const EditarPerfil = () => {
    const navigate = useNavigate();
    const usuarioLogeado = getUsuarioLogeado();

    const [usuario, setUsuario] = useState(null);
    const [perfil, setPerfil] = useState(null);
    const [posts, setPosts] = useState([]);
    const [activeTab, setActiveTab] = useState('todo');
    const [loading, setLoading] = useState(true);

    // Estados para edición
    const [editandoNombre, setEditandoNombre] = useState(false);
    const [editandoDescripcion, setEditandoDescripcion] = useState(false);
    const [nuevoNombre, setNuevoNombre] = useState('');
    const [nuevaDescripcion, setNuevaDescripcion] = useState('');

    // Verificar si el usuario está logeado
    useEffect(() => {
        console.log("=== CARGANDO EDITAR PERFIL ===");

        if (!usuarioLogeado) {
            console.log("No hay usuario logeado, redirigiendo...");
            navigate("/cuenta");
            return;
        }

        const { usuario: dataUsuario, perfil: dataPerfil } = usuarioLogeado;

        setUsuario(dataUsuario);
        setPerfil(dataPerfil);
        setNuevoNombre(dataPerfil.nom_usuario || dataUsuario.nombre);
        setNuevaDescripcion(dataPerfil.descripcion || '');

        // Cargar publicaciones del perfil
        cargarPublicaciones(dataPerfil.id);
    }, [navigate]);

    // Función para cargar publicaciones
    const cargarPublicaciones = async (perfilId) => {
        try {
            const publicaciones = await getPublicacionesPorPerfil(perfilId);

            const postsTransformados = publicaciones.map(pub => ({
                id: pub.id,
                author: pub.perfil.nom_usuario,
                avatar: pub.perfil.foto_perfil || "/user.svg",
                date: new Date(pub.fecha_creacion).toLocaleDateString(),
                content: pub.texto,
                image: pub.fotos_rutas && pub.fotos_rutas.length > 0 ? pub.fotos_rutas[0] : null,
                kudos: pub.likes_count || 0,
            }));

            setPosts(postsTransformados);
        } catch (error) {
            console.error("Error al cargar publicaciones:", error);
        } finally {
            setLoading(false);
        }
    };

    // Guardar cambios del nombre
    const guardarNombre = async () => {
        try {
            await actualizarPerfil(perfil.id, {
                nom_usuario: nuevoNombre
            });

            // Actualizar localStorage
            const updatedData = {
                ...usuarioLogeado,
                perfil: {
                    ...usuarioLogeado.perfil,
                    nom_usuario: nuevoNombre
                }
            };
            localStorage.setItem("usuarioLogeado", JSON.stringify(updatedData));

            setPerfil(prev => ({ ...prev, nom_usuario: nuevoNombre }));
            setEditandoNombre(false);
            alert("Nombre actualizado correctamente");
        } catch (error) {
            console.error("Error al actualizar nombre:", error);
            alert("Error al actualizar el nombre");
        }
    };

    // Guardar cambios de la descripción
    const guardarDescripcion = async () => {
        try {
            await actualizarPerfil(perfil.id, {
                descripcion: nuevaDescripcion
            });

            // Actualizar localStorage
            const updatedData = {
                ...usuarioLogeado,
                perfil: {
                    ...usuarioLogeado.perfil,
                    descripcion: nuevaDescripcion
                }
            };
            localStorage.setItem("usuarioLogeado", JSON.stringify(updatedData));

            setPerfil(prev => ({ ...prev, descripcion: nuevaDescripcion }));
            setEditandoDescripcion(false);
            alert("Descripción actualizada correctamente");
        } catch (error) {
            console.error("Error al actualizar descripción:", error);
            alert("Error al actualizar la descripción");
        }
    };

    if (loading || !usuario || !perfil) {
        return (
            <MainLayout tituloPagina="Editar Perfil" gridClass="editar-grid">
                <div className="edit-loading">
                    <p>Cargando...</p>
                </div>
            </MainLayout>
        );
    }

    return (
        <MainLayout tituloPagina="Editar Perfil" gridClass="editar-grid">
            <div className="edit-main-content">
                {/* === PERFIL === */}
                <div className="edit-cont-perfil">
                    <div className="edit-ima-perf">
                        <img src={perfil.foto_perfil || "/user.svg"} alt="foto de perfil" />
                        <button className="edit" title="Editar foto">
                            <i className="bi bi-pencil-square"></i>
                        </button>
                        <button className="delet" title="Eliminar foto">
                            <i className="bi bi-trash3"></i>
                        </button>
                    </div>

                    <div className="edit-descrip-perf">
                        {/* Nombre editable */}
                        <div className="edit-nom">
                            {editandoNombre ? (
                                <>
                                    <input
                                        type="text"
                                        value={nuevoNombre}
                                        onChange={(e) => setNuevoNombre(e.target.value)}
                                        style={{
                                            fontSize: '22px',
                                            padding: '5px',
                                            flex: 1
                                        }}
                                    />
                                    <button onClick={guardarNombre} title="Guardar">
                                        <i className="bi bi-check-lg"></i>
                                    </button>
                                    <button onClick={() => {
                                        setEditandoNombre(false);
                                        setNuevoNombre(perfil.nom_usuario);
                                    }} title="Cancelar">
                                        <i className="bi bi-x-lg"></i>
                                    </button>
                                </>
                            ) : (
                                <>
                                    <h2>{perfil.nom_usuario}</h2>
                                    <button 
                                        className="edit"
                                        onClick={() => setEditandoNombre(true)}
                                        title="Editar nombre"
                                    >
                                        <i className="bi bi-pencil-square"></i>
                                    </button>
                                </>
                            )}
                        </div>

                        {/* Descripción editable */}
                        <div className="edit-desc">
                            {editandoDescripcion ? (
                                <>
                                    <textarea
                                        value={nuevaDescripcion}
                                        onChange={(e) => setNuevaDescripcion(e.target.value)}
                                        style={{
                                            flex: 1,
                                            padding: '5px',
                                            fontSize: '14px',
                                            resize: 'none'
                                        }}
                                    />
                                    <div className="edit-desc-buttons">
                                        <button onClick={guardarDescripcion} title="Guardar">
                                            <i className="bi bi-check-lg"></i>
                                        </button>
                                        <button onClick={() => {
                                            setEditandoDescripcion(false);
                                            setNuevaDescripcion(perfil.descripcion);
                                        }} title="Cancelar">
                                            <i className="bi bi-x-lg"></i>
                                        </button>
                                    </div>
                                </>
                            ) : (
                                <>
                                    <p>{perfil.descripcion || "Sin descripción"}</p>
                                    <div className="edit-desc-buttons">
                                        <button 
                                            className="edit"
                                            onClick={() => setEditandoDescripcion(true)}
                                            title="Editar descripción"
                                        >
                                            <i className="bi bi-pencil-square"></i>
                                        </button>
                                    </div>
                                </>
                            )}
                        </div>
                    </div>
                </div>

                <hr />

                {/* === CONFIGURACIÓN DE PÁGINA === */}
                <div className="edit-page">
                    <h5>Configuración de Página</h5>
                    <div className="edit-color-page">
                        <label>Color de página: </label>
                        <div>
                            <button>Editar</button>
                            <button>Borrar</button>
                        </div>
                    </div>
                    <div className="edit-color-fondo">
                        <label>Color de fondo: </label>
                        <div>
                            <button>Editar</button>
                            <button>Borrar</button>
                        </div>
                    </div>
                    <div className="edit-image-fondo">
                        <label>Imagen de fondo: </label>
                        <div>
                            <button>Editar</button>
                            <button>Borrar</button>
                        </div>
                    </div>
                    <div className="edit-tipo-font">
                        <label>Tipo de letra: </label>
                        <div>
                            <button>Editar</button>
                            <button>Borrar</button>
                        </div>
                    </div>
                    <div className="edit-tam">
                        <label>Tamaño de letra: </label>
                        <input
                            type="range"
                            id="tam-font"
                            name="tam-font"
                            min="0"
                            max="40"
                            defaultValue="13"
                        />
                    </div>
                </div>

                <hr />

                {/* === POSTS / COMENTARIOS === */}
                <div className="edit-com-post">
                    <h5>Publicaciones</h5>

                    <div className="edit-pest">
                        <button 
                            className={activeTab === 'todo' ? 'active' : ''}
                            onClick={() => setActiveTab('todo')}
                        >
                            Todas
                        </button>
                    </div>

                    {/* Lista de publicaciones */}
                    <div className="content-edit">
                        <div className="all-post">
                            {posts.length === 0 ? (
                                <p style={{ textAlign: 'center', padding: '20px' }}>
                                    No tienes publicaciones
                                </p>
                            ) : (
                                posts.map((post) => (
                                    <div key={post.id} className="blog-post">
                                        <div className="post-perf">
                                            <div className="info-main">
                                                <img
                                                    className="ima-inf"
                                                    src={post.avatar}
                                                    alt={`avatar de ${post.author}`}
                                                />
                                                <h6 className="nombre">{post.author}</h6>
                                                <h6 className="public">Publicó</h6>
                                                <h6 className="fecha">{post.date}</h6>
                                            </div>
                                            <div className="post">
                                                <p>{post.content}</p>
                                            </div>
                                            {post.image && (
                                                <div className="post-ima">
                                                    <img
                                                        className="ima-pub"
                                                        src={post.image}
                                                        alt="imagen del post"
                                                    />
                                                </div>
                                            )}
                                            <div className="opciones-botton">
                                                <a className="check" href="#">
                                                    [check]
                                                </a>
                                                <button className="kudos">
                                                    <i className="bi bi-bug-fill"></i>
                                                </button>
                                                <div className="edit-buttons">
                                                    <button className="edit" title="Editar">
                                                        <i className="bi bi-pencil-square"></i>
                                                    </button>
                                                    <button className="delet" title="Eliminar">
                                                        <i className="bi bi-trash3"></i>
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>

                {/* Botón para volver al perfil */}
                <div style={{ marginTop: '20px', textAlign: 'center' }}>
                    <button
                        onClick={() => navigate('/perfil')}
                        style={{
                            padding: '10px 30px',
                            backgroundColor: '#1a4f9d',
                            color: 'white',
                            border: 'none',
                            borderRadius: '5px',
                            cursor: 'pointer',
                            fontSize: '16px'
                        }}
                    >
                        Volver al Perfil
                    </button>
                </div>
            </div>
        </MainLayout>
    );
};

export default EditarPerfil;
